/**
 * city-select 省市区级联选择器
 * @property {String Number} z-index 弹出时的z-index值（默认1075）
 * @property {Boolean} mask-close-able 是否允许通过点击遮罩关闭Picker（默认true）
 * @property {String} default-region 默认选中的地区，中文形式
 * @property {String} default-code 默认选中的地区，编号形式
 */
/* harmony default export */ __webpack_exports__["default"] = ({
  name: 'fa-citys',
  props: {
    // 通过双向绑定控制组件的弹出与收起
    value: {
      type: Boolean,
      default: false
    },
    // 默认显示地区的编码，areaCode可传类似["13", "1303", "130304"]
    areaCode: {
      type: Array,
      default() {
        return [];
      }
    },
    // 是否允许通过点击遮罩关闭Picker
    maskCloseAble: {
      type: Boolean,
      default: true
    },
    // 弹出的z-index值
    zIndex: {
      type: [String, Number],
      default: 0
    }
  },
  data() {
    return {
      cityValue: '',
      isChooseP: false,
      //是否已经选择了省
      province: 0,
      //省级下标
      provinces: [],
      isChooseC: false,
      //是否已经选择了市
      city: 0,
      //市级下标
      citys: [],
      isChooseA: false,
      //是否已经选择了区
      area: 0,
      //区级下标
      areas: [],
      tabsIndex: 0
    };
  },
  mounted() {
    this.init();
  },
  computed: {
    isChange() {
      return this.tabsIndex > 1;
    },
    genTabsList() {
      let tabsList = [{
        name: '请选择'
      }];
      if (this.isChooseP) {
        tabsList[0]['name'] = this.provinces[this.province]['label'];
        tabsList[1] = {
          name: '请选择'
        };
      }
      if (this.isChooseC) {
        tabsList[1]['name'] = this.citys[this.city]['label'];
        tabsList[2] = {
          name: '请选择'
        };
      }
      if (this.isChooseA) {
        tabsList[2]['name'] = this.areas[this.area]['label'];
      }
      return tabsList;
    },
    uZIndex() {
      // 如果用户有传递z-index值，优先使用
      return this.zIndex ? this.zIndex : this.$u.zIndex.popup;
    }
  },
  methods: {
    async getArea(type = '', id = '') {
      let where = {};
      if (type == 'citys') {
        where = {
          province: id
        };
      } else if (type == 'areas') {
        where = {
          city: id
        };
      }
      let res = await this.$api.area(where);
      if (res.code) {
        let key = type ? type : 'provinces';
        this[key] = res.data;
      }
    },
    async init() {
      if (this.areaCode.length == 3) {
        await this.setProvince('', this.areaCode[0]);
      } else {
        await this.getArea();
      }
    },
    async setProvince(label = '', value = '') {
      await this.getArea();
      this.provinces.map(async (v, k) => {
        if (value ? v.value == value : v.label == label) {
          await this.provinceChange(k);
          await this.setCity('', this.areaCode[1]);
        }
      });
    },
    async setCity(label = '', value = '') {
      this.citys.map(async (v, k) => {
        if (value ? v.value == value : v.label == label) {
          await this.cityChange(k);
          await this.setArea('', this.areaCode[2]);
        }
      });
    },
    async setArea(label = '', value = '') {
      this.areas.map((v, k) => {
        if (value ? v.value == value : v.label == label) {
          this.isChooseA = true;
          this.area = k;
          this.areaChange(k);
        }
      });
    },
    close() {
      this.$emit('input', false);
    },
    tabsChange(index) {
      this.tabsIndex = index;
    },
    async provinceChange(index) {
      this.isChooseP = true;
      this.isChooseC = false;
      this.isChooseA = false;
      this.province = index;
      await this.getArea('citys', this.provinces[index].value);
      this.tabsIndex = 1;
    },
    async cityChange(index) {
      this.isChooseC = true;
      this.isChooseA = false;
      this.city = index;
      await this.getArea('areas', this.citys[index].value);
      this.tabsIndex = 2;
    },
    areaChange(index) {
      this.isChooseA = true;
      this.area = index;
      let result = {};
      result.province = this.provinces[this.province];
      result.city = this.citys[this.city];
      result.area = this.areas[this.area];
      this.$emit('city-change', result);
      this.close();
    }
  }
});

